scripts.张琳心对话.txt:
// 张琳心同伴对话

	If ($Event == 230) @Event230;
	If ($Event == 240) @Event240;
	
	Return;

@Event230:	
	Say("张琳心：（爹爹呢？难道……）", 28);
	Return;
	
@Event240:
	If ($Talkmap011 == 0) @Talk0;
	If ($Talkmap011 == 1) @Talk1;
@Talk0:	
	Say("张琳心：想不到武夷派竟惨遭灭门之祸！", 24);
	Say("独孤剑：没想到五色教的手段这么毒辣！他们为什么要铲平武夷派？难道也是为了……血书？你父亲……", 9);
	Say("张琳心：不！我父亲和五色教绝对没有关系！你……你不要错怪他！", 26);
	Say("独孤剑：对不起，张姑娘，我只是觉得这一切实在太凑巧了……", 8);
	Say("张琳心：我们去临安城找我爹，把一切都问个一清二楚！", 28);
	Say("独孤剑：……", 1);
	Assign($Talkmap011, 1);
	Return;	
@Talk1:
	Say("张琳心：我们去临安城找我爹，把一切都问个一清二楚！", 28);
	Say("独孤剑：……", 1);
	Return;

