scripts.武夷派弟子对话3.txt:
// 武夷派弟子对话3
	
	If ($Talkwuyidizi == 0) @Talk0;
	If ($Talkwuyidizi == 1) @Talk1;
	
@Talk0:
	Say("武夷派弟子：师傅老是说衡山剑派的剑法不错，我可不服气，听说他们的大弟子独孤剑功夫不错，有机会我得和他比划比划。", 0);
